  1	/**
  2	 * tests/integration/build.test.ts
  3	 *
  4	 * End-to-end integration test for @mistralys/persona-builder.
  5	 *
  6	 * Calls build(config) against the project-level fixtures/ directory and
  7	 * asserts that:
  8	 *   - build() returns a successful BuildSummary
  9	 *   - At least one output file is written to disk
 10	 *   - The written file content matches the rendered BuildResult content
 11	 *   - The written file contains expected persona text (variable substitution
 12	 *     and partial resolution both worked)
 13	 *   - check mode (config.check = true) skips file writes but still renders
 14	 *   - The public API surface (src/index.ts) exports all required symbols
 15	 *
 16	 * This test covers WP-007 acceptance criteria (core build/check pipeline and public API
 17	 * exports) and WP-009 acceptance criteria (deep-agents target build and three-target
 18	 * integration, added in the WP-009 QA rework).
 19	 */
 20	
 21	import { describe, it, expect, afterEach } from 'vitest';
 22	import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
 23	import { existsSync } from 'node:fs';
 24	import path from 'node:path';
 25	import { fileURLToPath } from 'node:url';
 26	
 27	// Import through the public API barrel (src/index.ts) to exercise all required exports
 28	import {
 29	  build,
 30	  TargetRegistry,
 31	  type BuildConfig,
 32	  type BuildSummary,
 33	  type PersonaBuildPlugin,
 34	  type TargetType,
 35	  type ValidationResult,
 36	} from '../../src/index.js';
 37	
 38	// ---------------------------------------------------------------------------
 39	// Fixture paths
 40	// ---------------------------------------------------------------------------
 41	
 42	const __dirname = path.dirname(fileURLToPath(import.meta.url));
 43	const FIXTURES_ROOT = path.resolve(__dirname, '../../fixtures');
 44	const SAMPLE_SUITE_DIR = path.join(FIXTURES_ROOT, 'sample-suite');
 45	const SHARED_PARTIALS_DIR = path.join(FIXTURES_ROOT, 'shared', 'partials');
 46	const OUT_ROOT = path.join(FIXTURES_ROOT, 'integration-out');
 47	
 48	// ---------------------------------------------------------------------------
 49	// Cleanup after each test (remove any written output files)
 50	// ---------------------------------------------------------------------------
 51	
 52	afterEach(async () => {
 53	  await rm(OUT_ROOT, { recursive: true, force: true });
 54	});
 55	
 56	// ---------------------------------------------------------------------------
 57	// Public API surface check
 58	// ---------------------------------------------------------------------------
 59	
 60	describe('public API exports (WP-007 AC-3)', () => {
 61	  it('exports build as a function', () => {
 62	    expect(typeof build).toBe('function');
 63	  });
 64	
 65	  it('type exports compile without error (BuildConfig, BuildSummary, PersonaBuildPlugin, TargetType, ValidationResult)', () => {
 66	    // These are compile-time checks — the fact that this file imports and uses
 67	    // the types without error validates the export surface.
 68	    const _configShape: Partial<BuildConfig> = { suites: {} };
 69	    const _summaryShape: Partial<BuildSummary> = { success: true, results: [], strictFailures: [], totalBuilt: 0, totalWritten: 0 };
 70	    const _pluginShape: Partial<PersonaBuildPlugin> = { name: 'test' };
 71	    const _targetType: TargetType = 'vscode';
 72	    const _validationResult: ValidationResult = { severity: 'info', message: 'ok' };
 73	
 74	    expect(_configShape.suites).toBeDefined();
 75	    expect(_summaryShape.success).toBe(true);
 76	    expect(_pluginShape.name).toBe('test');
 77	    expect(_targetType).toBe('vscode');
 78	    expect(_validationResult.severity).toBe('info');
 79	  });
 80	});
 81	
 82	// ---------------------------------------------------------------------------
 83	// Integration test: build() against fixtures/ (VS Code target)
 84	// ---------------------------------------------------------------------------
 85	
 86	describe('build() integration — VS Code target (WP-007 AC-4)', () => {
 87	  it('writes at least one output file with correct content', async () => {
 88	    const outVscode = path.join(OUT_ROOT, 'vscode');
 89	    const outClaudeCode = path.join(OUT_ROOT, 'claude-code');
 90	
 91	    const config: BuildConfig = {
 92	      suites: {
 93	        sample: {
 94	          srcDir: SAMPLE_SUITE_DIR,
 95	          outputDirs: {
 96	            vscode: outVscode,
 97	            'claude-code': outClaudeCode,
 98	          },
 99	        },
100	      },

101	      sharedPartialsDir: SHARED_PARTIALS_DIR,
102	      targets: ['vscode'],
103	    };
104	
105	    const summary: BuildSummary = await build(config);
106	
107	    // Build must succeed
108	    expect(summary.success).toBe(true);
109	    expect(summary.totalBuilt).toBeGreaterThanOrEqual(1);
110	    expect(summary.totalWritten).toBeGreaterThanOrEqual(1);
111	
112	    // At least one result must have written=true
113	    const written = summary.results.filter((r) => r.written);
114	    expect(written.length).toBeGreaterThanOrEqual(1);
115	
116	    // The VS Code output for example-persona uses vs_file_name = 'example-persona.agent.md'
117	    const vsResult = summary.results.find(
118	      (r) => r.target === 'vscode' && path.basename(r.outputPath) === 'example-persona.agent.md',
119	    );
120	    expect(vsResult).toBeDefined();
121	    expect(vsResult!.written).toBe(true);
122	
123	    // File must exist on disk
124	    expect(existsSync(vsResult!.outputPath)).toBe(true);
125	
126	    // Disk content must match rendered content
127	    const diskContent = await readFile(vsResult!.outputPath, 'utf8');
128	    expect(diskContent).toBe(vsResult!.content);
129	
130	    // Content correctness: variable substitution
131	    expect(diskContent).toContain('Example Persona');
132	    expect(diskContent).toContain('1.0.0'); // default_version from _shared.yaml
133	    expect(diskContent).toContain('A minimal example persona for integration testing.');
134	
135	    // Content correctness: partial resolution ({{> greeting}} → greeting.md)
136	    expect(diskContent).toContain('Hello, I am Example Persona.');
137	
138	    // Frontmatter should be present
139	    expect(diskContent).toMatch(/^---\n/);
140	    expect(diskContent).toContain("name: 'Example Persona v1.0.0'");
141	  });
142	
143	  it('result.content matches the file written to disk', async () => {
144	    const outVscode = path.join(OUT_ROOT, 'vscode-content-check');
145	    const outClaudeCode = path.join(OUT_ROOT, 'cc-content-check');
146	
147	    const config: BuildConfig = {
148	      suites: {
149	        sample: {
150	          srcDir: SAMPLE_SUITE_DIR,
151	          outputDirs: {
152	            vscode: outVscode,
153	            'claude-code': outClaudeCode,
154	          },
155	        },
156	      },
157	      sharedPartialsDir: SHARED_PARTIALS_DIR,
158	      targets: ['vscode'],
159	    };
160	
161	    const summary = await build(config);
162	
163	    for (const result of summary.results.filter((r) => r.written)) {
164	      const onDisk = await readFile(result.outputPath, 'utf8');
165	      expect(onDisk).toBe(result.content);
166	    }
167	  });
168	});
169	
170	// ---------------------------------------------------------------------------
171	// Integration test: both targets
172	// ---------------------------------------------------------------------------
173	
174	describe('build() integration — both targets', () => {
175	  it('produces both vscode and claude-code output files', async () => {
176	    const outVscode = path.join(OUT_ROOT, 'both', 'vscode');
177	    const outClaudeCode = path.join(OUT_ROOT, 'both', 'claude-code');
178	
179	    const config: BuildConfig = {
180	      suites: {
181	        sample: {
182	          srcDir: SAMPLE_SUITE_DIR,
183	          outputDirs: {
184	            vscode: outVscode,
185	            'claude-code': outClaudeCode,
186	          },
187	        },
188	      },
189	      sharedPartialsDir: SHARED_PARTIALS_DIR,
190	      // targets defaults to ['vscode', 'claude-code']
191	    };
192	
193	    const summary = await build(config);
194	
195	    expect(summary.success).toBe(true);
196	    // Two targets × one persona = 2 results
197	    expect(summary.totalBuilt).toBe(2);
198	    expect(summary.totalWritten).toBe(2);
199	
200	    const vsResult = summary.results.find((r) => r.target === 'vscode');
201	    const ccResult = summary.results.find((r) => r.target === 'claude-code');
202	
203	    expect(vsResult).toBeDefined();
204	    expect(ccResult).toBeDefined();
205	
206	    // Both files should exist
207	    expect(existsSync(vsResult!.outputPath)).toBe(true);
208	    expect(existsSync(ccResult!.outputPath)).toBe(true);
209	
210	    // VS Code output filename
211	    expect(path.basename(vsResult!.outputPath)).toBe('example-persona.agent.md');
212	    // Claude Code output filename
213	    expect(path.basename(ccResult!.outputPath)).toBe('example-persona.md');
214	  });
215	});
216	
217	// ---------------------------------------------------------------------------
218	// Integration test: check mode (no writes)
219	// ---------------------------------------------------------------------------
220	
221	describe('build() integration — check mode', () => {
222	  it('does not write any files to disk when check=true', async () => {
223	    const outVscode = path.join(OUT_ROOT, 'check', 'vscode');
224	    const outClaudeCode = path.join(OUT_ROOT, 'check', 'claude-code');
225	
226	    const config: BuildConfig = {
227	      suites: {
228	        sample: {
229	          srcDir: SAMPLE_SUITE_DIR,
230	          outputDirs: {
231	            vscode: outVscode,
232	            'claude-code': outClaudeCode,
233	          },
234	        },
235	      },
236	      sharedPartialsDir: SHARED_PARTIALS_DIR,
237	      targets: ['vscode'],
238	      check: true,
239	    };
240	
241	    const summary = await build(config);
242	
243	    expect(summary.success).toBe(true);
244	    expect(summary.totalBuilt).toBeGreaterThanOrEqual(1);
245	    // No files should be written
246	    expect(summary.totalWritten).toBe(0);
247	    expect(summary.results.every((r) => !r.written)).toBe(true);
248	
249	    // Output directory must NOT have been created
250	    expect(existsSync(outVscode)).toBe(false);
251	
252	    // Content is still rendered even in check mode
253	    expect(summary.results[0]?.content).toBeTruthy();
254	    expect(summary.results[0]?.content).toContain('Example Persona');
255	  });
256	});
257	
258	// ---------------------------------------------------------------------------
259	// Integration test: plugin hooks are invoked
260	// ---------------------------------------------------------------------------
261	
262	describe('build() integration — plugin hooks', () => {
263	  it('invokes onBuildContext and onPostRender hooks for each persona', async () => {
264	    const outVscode = path.join(OUT_ROOT, 'plugins', 'vscode');
265	    const outClaudeCode = path.join(OUT_ROOT, 'plugins', 'claude-code');
266	
267	    const contextCallLog: string[] = [];
268	    const postRenderCallLog: string[] = [];
269	
270	    const testPlugin: PersonaBuildPlugin = {
271	      name: 'integration-test-plugin',
272	      onBuildContext(context) {
273	        contextCallLog.push(String(context['name'] ?? 'unknown'));
274	        return context;
275	      },
276	      onPostRender(output, persona, target) {
277	        postRenderCallLog.push(`${persona.name}:${target}`);
278	        return output;
279	      },
280	    };
281	
282	    const config: BuildConfig = {
283	      suites: {
284	        sample: {
285	          srcDir: SAMPLE_SUITE_DIR,
286	          outputDirs: {
287	            vscode: outVscode,
288	            'claude-code': outClaudeCode,
289	          },
290	        },
291	      },
292	      sharedPartialsDir: SHARED_PARTIALS_DIR,
293	      targets: ['vscode'],
294	      plugins: [testPlugin],
295	      check: true,
296	    };
297	
298	    const summary = await build(config);
299	
300	    expect(summary.success).toBe(true);

301	    expect(contextCallLog.length).toBeGreaterThanOrEqual(1);
302	    expect(postRenderCallLog.length).toBeGreaterThanOrEqual(1);
303	
304	    // Plugin should have seen the example-persona name
305	    expect(contextCallLog).toContain('Example Persona');
306	    expect(postRenderCallLog).toContain('Example Persona:vscode');
307	  });
308	});
309	
310	// ---------------------------------------------------------------------------
311	// Integration test: cross-suite agent name variable resolution
312	// ---------------------------------------------------------------------------
313	
